-- Pesquisa de satisfação anônima + formulário identificado "Continue com a ComuniCALI" (aberto por um botão no fim da pesquisa).
update public.forms set
  description = $t$Obrigada por viver o primeiro encontro com a gente. Esta pesquisa é anônima: nenhuma resposta fica ligada ao seu nome ou ao seu e-mail. Leva cerca de 3 minutos.

Sua opinião decide o que mantemos, o que mudamos e o que criamos para a próxima edição.$t$,
  success_text = $t$Obrigada pela sua opinião! Ela é anônima e já está com a gente. Quer saber dos próximos passos, dos próximos encontros e da comunidade, e como continuar participando? Isso fica em outro formulário, identificado e separado desta pesquisa, que abre em uma nova aba.
[Quero saber os próximos passos](/f/continuar-com-a-comunidade)$t$,
  questions = (select jsonb_agg(q order by ord) from jsonb_array_elements(questions) with ordinality as t(q, ord) where q->>'id' not in ('depoimento','nome','citar','imagem'))
where slug = 'pesquisa-1a-edicao';
insert into public.forms (slug, title, description, thank_you, status, category, audience, questions, confirm_email, submit_label, success_text)
values ('continuar-com-a-comunidade', 'Continue com a ComuniCALI', $t$Obrigada por estar no primeiro encontro. Este formulário é separado da pesquisa de satisfação: aqui você se identifica, e nada se liga às respostas anônimas que você deu antes.

Você pode estar com dúvida sobre membro, visitante e convidado. A gente não imaginava que o encontro tomaria a proporção que tomou, nem que receberia o apoio que recebeu. Por isso algumas coisas mudaram desde o início da organização, e o seu crachá foi feito antes dessa mudança. Quem decidir seguir com a gente na comunidade vai receber a explicação completa de cada categoria.$t$, '', 'open', 'Pesquisa', 'cali', $t$[{"id": "nome", "kind": "short_text", "label": "Qual é o seu nome completo?", "required": true}, {"id": "email", "kind": "email", "label": "Qual é o e-mail que você usou na inscrição e no check-in?", "help": "Usamos este e-mail para reconhecer a sua participação.", "required": true}, {"id": "tipo", "kind": "single_choice", "label": "Como você participou do encontro?", "options": ["Como convidado", "Como visitante ou membro"], "required": true}, {"id": "convidou", "kind": "short_text", "label": "Quem convidou você?", "showIf": {"id": "tipo", "in": ["Como convidado"]}}, {"id": "interesse", "kind": "single_choice", "label": "Deseja saber dos próximos passos, dos próximos encontros e da comunidade, e como continuar participando?", "options": ["Sim, quero saber", "Agora não"], "required": true}, {"id": "email_novo", "kind": "email", "label": "Quer receber as novidades em outro e-mail?", "help": "Se sim, escreva aqui. Se o e-mail acima serve, é só avançar.", "showIf": {"id": "interesse", "in": ["Sim, quero saber"]}}, {"id": "depoimento", "kind": "long_text", "label": "Se quiser, deixe um depoimento sobre o encontro, para compartilharmos com a comunidade."}, {"id": "citar", "kind": "single_choice", "label": "Podemos citar uma frase sua, com o seu nome, nos materiais da ComuniCALI?", "options": ["Sim", "Não"], "required": true}, {"id": "imagem", "kind": "yes_no", "label": "Autoriza o uso da sua imagem em fotos e vídeos do encontro, publicados pela CALI RH?", "required": true}]$t$::jsonb, false, 'Enviar', $t$Recebemos o seu formulário! Obrigada por seguir com a gente. Em breve você recebe novidades da ComuniCALI.$t$)
on conflict (slug) do update set description = excluded.description, questions = excluded.questions, success_text = excluded.success_text, title = excluded.title;
